// github.com 被网络环境解析到非公网 IP，web_fetch 不可用。改问本地 git：远程 URL 是 https 匿名可达型还是私有
const r = await tools.pwsh({
  command: `
git -C "D:\\GitHub\\My-second-brain" remote -v
# 探测匿名可达性：ls-remote 不带凭证，公开仓库会成功返回 ref
$env:GIT_TERMINAL_PROMPT = 0
git ls-remote https://github.com/jjq1993148743/My-second-brain.git HEAD 2>&1 | Out-String
`,
  description: "探测仓库匿名可达性"
});
console.log(r.stdout);
